import { useEffect, useState } from "react";
import MapaMexico from "./MapaMexico";
import "./components/Inicio.css"; // Ruta correcta del CSS

function Inicio() {
  const [sismos, setSismos] = useState([]); // Lista de sismos
  const [menuVisible, setMenuVisible] = useState(false); // Control del menú
  const [sismoSeleccionado, setSismoSeleccionado] = useState(null);
  const [coordenadas, setCoordenadas] = useState(null);
  const [theme, setTheme] = useState("light"); // Tema actual (claro por defecto)

  // Cambiar el tema
  const toggleTheme = () => {
    const newTheme = theme === "light" ? "dark" : "light"; // Alternar entre "light" y "dark"
    setTheme(newTheme);
    document.body.setAttribute("data-theme", newTheme); // Cambiar el atributo del body
  };

  useEffect(() => {
    // Obtener la lista de sismos desde la API
    fetch("http://localhost:9090/inicio", {
      method: "GET",
      headers: { "Content-Type": "application/json" },
    })
      .then((response) => {
        if (!response.ok) throw new Error("Error en la respuesta del servidor");
        return response.json();
      })
      .then((data) => {
        console.log("Sismos obtenidos:", data);
        setSismos(data);
      })
      .catch((error) => console.error("Error al obtener datos:", error));
  }, []);

  const handleSismoClick = (sismo) => {
    setSismoSeleccionado(sismo);
    setCoordenadas({ lat: sismo.latitud, lng: sismo.longitud });
  };

  return (
    <div className="container">
      {/* Botón de menú */}
      <button
        className="menu-btn"
        onClick={() => setMenuVisible(!menuVisible)}
      >
        &#9776;
      </button>

      {/* Switch del Tema */}
      <div className="theme-switch-container">
        <label className="switch">
          <input
            type="checkbox"
            onChange={toggleTheme}
            checked={theme === "dark"} // El estado del toggle depende del tema actual
          />
          <span className="slider"></span>
        </label>
        <span className="theme-label">
          {theme === "light" ? "Modo Claro" : "Modo Oscuro"}
        </span>
      </div>

      {/* Contenedor del Mapa */}
      <div className="map-container">
        <MapaMexico coordenadas={coordenadas} />
      </div>

      {/* Menú lateral */}
      <div className={`sidebar ${menuVisible ? "visible" : ""}`}>
        <button className="close-btn" onClick={() => setMenuVisible(false)}>
          &times;
        </button>
        <ul className="sismos-list">
          {sismos.map((sismo, index) => (
            <li
              key={index}
              className="sismo-item"
              onClick={() => handleSismoClick(sismo)}
            >
              {sismo.referenciaLocalizacion} - Magnitud: {sismo.magnitud}
            </li>
          ))}
        </ul>
        {sismoSeleccionado && (
          <div className="sismo-info">
            <h3>Detalles del Sismo</h3>
            <p><b>Ubicación:</b> {sismoSeleccionado.referenciaLocalizacion}</p>
            <p><b>Magnitud:</b> {sismoSeleccionado.magnitud}</p>
            <p><b>Fecha:</b> {sismoSeleccionado.fecha} {sismoSeleccionado.hora}</p>
            <p><b>Profundidad:</b> {sismoSeleccionado.profundidad} km</p>
            <p>
              <b>Latitud:</b> {sismoSeleccionado.latitud}, <b>Longitud:</b> {sismoSeleccionado.longitud}
            </p>
            <p><b>Estatus:</b> {sismoSeleccionado.estatus}</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default Inicio;
